/// One step of the 2nd-order **Runge–Kutta** (explicit midpoint) method for
/// `dy/dt = f(t, y)`.
///
/// Evaluates the slope once at the interval start and once at the midpoint,
/// advancing with the midpoint slope: global error `O(h^2)`, one order better
/// than explicit Euler for one extra function evaluation.
///
/// Generated by kovan-codegen (docs/kovan.md § "Numerical Methods → ODE
/// Solvers"). Deterministic template; depends only on `core`/`std` `f64`.
pub fn rk2_step<F>(f: &F, t: f64, y: f64, h: f64) -> f64
where
    F: Fn(f64, f64) -> f64,
{
    let k1 = f(t, y);
    let k2 = f(t + 0.5 * h, y + 0.5 * h * k1);
    y + h * k2
}

/// Integrate `dy/dt = f(t, y)` from `(t0, y0)` for `n` steps of size `h` with
/// the explicit-midpoint RK2 method, returning the `(t, y)` trajectory
/// (length `n + 1`).
pub fn rk2_integrate<F>(f: F, t0: f64, y0: f64, h: f64, n: usize) -> Vec<(f64, f64)>
where
    F: Fn(f64, f64) -> f64,
{
    let mut out = Vec::with_capacity(n + 1);
    let mut t = t0;
    let mut y = y0;
    out.push((t, y));
    for _ in 0..n {
        y = rk2_step(&f, t, y, h);
        t += h;
        out.push((t, y));
    }
    out
}
